ST.xhtml:p:
R_TringOpen(CLK := g_bTwoSidesCenterOpenM);
R_TringClose(CLK := g_bTwoSidesCenterCloseM);
R_TringSetValue(CLK := g_bFourSidesCenterSetValueM);
R_TringManula(CLK := bManualHMI);
IF R_TringOpen.Q THEN
  g_bTwoSidesCenterOpenM := FALSE;
  ntwosidesstate := 10;
  g_dUseSideCenterType := 5.0;
  g_bExecuteSingeSideOnAFace := FALSE;
  g_bExecuteSingeSideOnBFace := FALSE;
  g_bExecuteSingeSideOnCFace := FALSE;
  g_bExecuteSingeSideOnDFace := FALSE;
END_IF;
IF R_TringClose.Q THEN
  g_bTwoSidesCenterCloseM := FALSE;
  ntwosidesstate := 20;
END_IF;
IF R_TringManula.Q THEN
  g_dInformHmiUpdateValue := 6.0;
  bManualHMI := FALSE;
END_IF;

g_dTwoSidesCompensationValueA := g_dTwoSidesCenterCompensationA; 
g_dTwoSidesCompensationValueB := g_dTwoSidesCenterCompensationB; 
CASE ntwosidesstate OF
  0:
  ntwosidesstate := 0;
  10:
  IF R_TringSetValue.Q THEN
    IF g_nFourSidesCenterSetValueP = 0 THEN
      dTwoSidesCompensationA := g_dFourSidesCenterSetValueQ;
    ELSIF g_nFourSidesCenterSetValueP = 1 THEN
      dTwoSidesCompensationB := g_dFourSidesCenterSetValueQ;
    END_IF;
    g_bFourSidesCenterSetValueM := FALSE;
  END_IF;
    IF g_bPlcPauseBuffer THEN
      ntwosidesstate := 30;
    END_IF;
  20:
    g_dTwoSidesCenterCompensationA := dTwoSidesCompensationA - g_dBeamCenterPos;
    g_dTwoSidesCenterCompensationB := dTwoSidesCompensationB - g_dBeamCenterPos;
    g_dInformHmiUpdateValue := 6.0;
    ntwosidesstate := 0;
    IF ABS(g_dTwoSidesCenterCompensationA)>g_dCompensationThreshold OR ABS(g_dTwoSidesCenterCompensationB) > g_dCompensationThreshold THEN
      g_bExcessiveDeviationOfCentringCompensationAlarm := TRUE;
    END_IF;
  30:
    IF g_bPlcStartBuffer THEN
      ntwosidesstate := 10;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer OR g_bPlcEndM THEN
  ntwosidesstate := 0;
END_IF;
